-- Applied 22 Nov 2026 (migrations hub_chk_mca_splits + hub_chk_mca_move_adt1_papers).
-- NOTE: hub_cmp_docs_stamp pins parent_id on update, so the paper move needed the trigger switched off for that one statement.
-- MCA / ROC: five combined questions split (MC03/MC10, MC04/MC11, MC06/MC12, MC07/MC13, MC09/MC14).
update public.hub_chk_points set q='Is the auditor properly appointed?', why='Accounts cannot be validly signed otherwise.', law='Companies Act 2013 s.139', applies='company', evidence='Appointment resolution / minutes', updated_at=now() where code='MC03';
update public.hub_chk_points set q='Is director KYC (DIR-3 KYC) done for every director?', why='A deactivated DIN blocks all filings.', law='Companies (Appointment) Rules r.12A', applies='company', evidence='KYC status', updated_at=now() where code='MC04';
update public.hub_chk_points set q='Are loans from directors and relatives backed by declarations?', why='Money from others can be treated as illegal deposits.', law='Companies (Acceptance of Deposits) Rules 2014', applies='company', evidence='Declarations', updated_at=now() where code='MC06';
update public.hub_chk_points set q='Are dealings with the other Velite firms approved by the board?', why='Directors are personally liable for unapproved related-party deals.', law='Companies Act 2013 s.188', applies='company', evidence='Board resolution', updated_at=now() where code='MC07';
update public.hub_chk_points set q='Are share certificates issued and stamped?', why='Proves ownership clearly.', law='Companies Act 2013 s.56', applies='company', evidence='Share register + certificates', updated_at=now() where code='MC09';
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('MC10','MCA / ROC','Is ADT-1 filed with the ROC?','An appointment not reported on ADT-1 is not complete.','Companies Act 2013 s.139','company',array[]::text[],'M','ADT-1 + receipt',6001,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('MC11','MCA / ROC','Are the directors'' digital signatures valid?','An expired signature stops every ROC filing.','Companies (Registration Offices and Fees) Rules; IT Act 2000','company',array[]::text[],'M','DSC expiry list',6002,true,'LG03') on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('MC12','MCA / ROC','Are such loans reported in DPT-3?','Money from others can be treated as illegal deposits.','Companies (Acceptance of Deposits) Rules 2014','company',array[]::text[],'M','DPT-3',6003,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('MC13','MCA / ROC','Are dealings with the other Velite firms entered in the register of contracts (MBP-4)?','The register of contracts is a statutory register.','Companies Act 2013 s.189','company',array[]::text[],'M','MBP-4 register',6004,true,null) on conflict (code) do nothing;
insert into public.hub_chk_points(code,dept,q,why,law,applies,tags,risk,evidence,sort,active,lic) values ('MC14','MCA / ROC','Is the beneficial-owner declaration in place (BEN-2)?','Significant beneficial owners must be declared.','Companies Act 2013 s.90','company',array[]::text[],'M','BEN-2',6005,true,null) on conflict (code) do nothing;
